	@Test
	void sameRequestSparqlDelegationRetainsUnboundGraphQueries() throws Exception {
		SPARQLProtocolSession session = mock(SPARQLProtocolSession.class);
		String text = "SELECT ?g ?s ?o WHERE { GRAPH ?g { ?s <urn:p> ?o } }";
		List<String> requests = new ArrayList<>();
		when(session.sendTupleQuery(any(QueryLanguage.class), anyString(), nullable(String.class),
				nullable(Dataset.class), anyBoolean(), anyInt(), ArgumentMatchers.<WeakReference<?>>isNull(),
				any(Binding[].class))).thenAnswer(invocation -> {
					requests.add(invocation.getArgument(1));
					Binding[] bindings = (Binding[]) invocation.getRawArguments()[7];
					assertThat(bindings).isEmpty();
					try (RepositoryConnection connection = data.getConnection();
							var rows = connection.prepareTupleQuery(invocation.<String>getArgument(1)).evaluate()) {
						return new IteratingTupleQueryResult(rows.getBindingNames(), QueryResults.asList(rows));
					}
				});
		SPARQLRepository repository = sparqlRepository(session);
		var federation = FedXFactory.newFederation()
				.withMembers(List.of(EndpointFactory.loadEndpoint("remote", repository)))
				.create();
		federation.init();
		try {
			try (RepositoryConnection connection = federation.getConnection();
					var rows = connection.prepareTupleQuery(text).evaluate()) {
				List<BindingSet> result = QueryResults.asList(rows);
				assertThat(result).hasSize(2).allSatisfy(row -> {
					assertThat(row.getValue("g")).isInstanceOf(RemoteBNode.class);
					RemoteBNode.Provenance provenance = ((RemoteBNode) row.getValue("g")).getProvenance();
					assertThat(provenance).isNotNull();
					assertThat(provenance.identityScope()).isNull();
					assertThat(provenance.canonicalResultID()).isFalse();
					assertThat(provenance.remoteID()).isEqualTo(GRAPH.getID());
				});
				assertThat(result.stream().map(row -> row.getValue("g")).distinct()).hasSize(1);
			}
			assertThat(requests).containsExactly(text);
		} finally {
			federation.shutDown();
			repository.shutDown();
		}
	}

	@Test
	void serializedPrivateFrameProbeIsNotTransportedToService() throws Exception {
		SPARQLProtocolSession session = mock(SPARQLProtocolSession.class);
		AtomicInteger requests = new AtomicInteger();
		when(session.sendTupleQuery(any(QueryLanguage.class), anyString(), nullable(String.class),
				nullable(Dataset.class), anyBoolean(), anyInt(), ArgumentMatchers.<WeakReference<?>>isNull(),
				any(Binding[].class))).thenAnswer(invocation -> {
					requests.incrementAndGet();
					assertThat((String) invocation.getArgument(1)).doesNotContain("urn:private-frame-probe");
					Binding[] bindings = (Binding[]) invocation.getRawArguments()[7];
					assertThat(bindings).extracting(Binding::getName).doesNotContain("s");
					QueryBindingSet row = new QueryBindingSet();
					row.addBinding("o", VF.createLiteral("remote"));
					return new IteratingTupleQueryResult(List.of("o"), List.of(row));
				});
		SPARQLRepository repository = sparqlRepository(session);
		QueryBindingSet privateProbe = new QueryBindingSet();
		privateProbe.addBinding("s", VF.createIRI("urn:private-frame-probe"));
		BindingSet framed = BindingFrameBindings.push(new BindingFrameBindings.Scope(), EmptyBindingSet.getInstance(),
				privateProbe, new QueryEvaluationContext.Minimal(null));
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(framed);
		}
		BindingSet restored;
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			restored = (BindingSet) input.readObject();
		}
		assertThat(BindingFrameBindings.probeValue(restored, "s")).isEqualTo(VF.createIRI("urn:private-frame-probe"));
		assertThat(restored.hasBinding("s")).isFalse();
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", P), Var.of("o"));
		Service expression = new Service(Var.of("endpoint", VF.createIRI("urn:service")), pattern,
				"?s <urn:p> ?o .", Map.of(), null, false);
		RepositoryFederatedService service = new RepositoryFederatedService(repository);
		try {
			try (var rows = service.select(expression, Set.of("o"), restored, null)) {
				assertThat(rows.next().getValue("o")).isEqualTo(VF.createLiteral("remote"));
			}
			assertThat(requests).hasValue(1);
		} finally {
			service.shutdown();
			repository.shutDown();
		}
	}

	@Test
	void plainStatementSourceSelectionPreservesTheExplicitDataset() {
		Value graph = new EndpointIdentity(endpoint(data), queryInfo).incoming(GRAPH);
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s"),
				Var.of("p", P, true, true), Var.of("o"), Var.of("g", graph, true, true));
		SparqlTripleSource source = source(data);
		assertThat(source.hasStatements(pattern, EmptyBindingSet.getInstance(), queryInfo, null)).isTrue();
		SimpleDataset dataset = new SimpleDataset();
		dataset.addNamedGraph(VF.createIRI("urn:allowed"));
		assertThat(source.hasStatements(pattern, EmptyBindingSet.getInstance(), queryInfo, dataset)).isFalse();
		pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s"),
				Var.of("p", P, true, true), Var.of("o"), Var.of("g"));
		QueryBindingSet bindings = new QueryBindingSet();
		bindings.addBinding("g", graph);
		assertThat(source.hasStatements(pattern, bindings, queryInfo, null)).isTrue();
		assertThat(source.hasStatements(pattern, bindings, queryInfo, dataset)).isFalse();
	}

